f\"\\nMatrix A: {A}\")\nprint(f\"Vector B: {B}\")\n\n# Solve using Gaussian elimination with partial pivoting\ndef solve_linear(A, b):\n    n = len(A)\n    M = [A[i][:] + [b[i]] for i in range(n)]\n    \n    for i in range(n):\n        # Find pivot\n        max_row = i\n        for r in range(i+1, n):\n            if abs(M[r][i]) > abs(M[max_row][i]):\n                max_row = r\n        M[i], M[max_row] = M[max_row], M[i]\n        \n        if abs(M[i][i]) < 1e-10:\n            continue\n        \n        for r in range(i+1, n):\n            factor = M[r][i] / M[i][i]\n            for c in range(i, n+1):\n                M[r][c] -= factor * M[i][c]\n    \n    x = [0] * n\n    for i in range(n-1, -1, -1):\n        if abs(M[i][i]) < 1e-10:\n            x[i] = 0\n        else:\n            x[i] = M[i][n] - sum(M[i][j] * x[j] for j in range(i+1, n))\n            x[i] /= M[i][i]\n    return x\n\n# Solve for [a, b, c]\nresult = solve_linear(A, B)\na, b, c = result\n\nprint(f\"\\nQuadratic coefficients: a={a}, b={b}, c={c}\")\n\n# Verify the fit\nprint(\"\\nFitting verification:\")\nfor ti, yi in zip(t, y):\n    y_fit = a*ti**2 + b*ti + c\n    print(f\"t={ti}: actual={yi}, fitted={y_fit}, diff={yi-y_fit}\")\n\n# Predict for t=5 (September)\nt_pred = 5\ny_pred = a*t_pred**2 + b*t_pred + c\nprint(f\"\\nPredicted September value (t=5): {y_pred}\")\n\n# Germany invaded Poland on September 1, 1939\ninvasion_day = 1\n\n# Divide predicted September value by invasion day number\nresult_val = y_pred / invasion_day\nprint(f\"Invasion day: {invasion_day}\")\nprint(f\"Result: {y_pred} / {invasion_day} = {result_val}\")\n\n# Round to nearest whole number\nrounded_result = round(result_val)\nprint(f\"\\nFinal result (rounded): {rounded_result}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
